#!/usr/bin/env python3
# Bridge between a board and the editor: the GRAFCET generated by the editor
# and built with -DGRAFCET_DEBUG on an Arduino writes its steps and its
# firings on Serial, one JSON object per line. This script publishes these
# lines on ZeroMQ, where the editor reads them (Debug > Connect,
# tcp://localhost:5556), as from a program on the computer.
#
#   pip install pyserial pyzmq
#   python3 tools/serial-bridge.py /dev/ttyACM0 [115200] [tcp://*:5556]
#
# The sketch shall start the serial line at the same speed:
#   void setup() { Serial.begin(115200); }

import json
import sys

import serial
import zmq


def main():
    if len(sys.argv) < 2:
        print("Usage: serial-bridge.py <port> [baudrate] [endpoint]")
        return 2
    port = sys.argv[1]
    baudrate = int(sys.argv[2]) if len(sys.argv) > 2 else 115200
    endpoint = sys.argv[3] if len(sys.argv) > 3 else "tcp://*:5556"

    socket = zmq.Context().socket(zmq.PUB)
    socket.bind(endpoint)
    print(f"{port} at {baudrate} bauds -> {endpoint} (Ctrl+C to stop)")
    with serial.Serial(port, baudrate, timeout=1) as line:
        while True:
            text = line.readline().decode("utf-8", errors="replace").strip()
            if not text:
                continue
            # Only the messages of the GRAFCET: the sketch may print other lines.
            try:
                json.loads(text)
            except ValueError:
                print("(not for the editor) " + text)
                continue
            socket.send_string(text)


if __name__ == "__main__":
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        pass
